import{_ as a,c as n,o as r,ag as t}from"./chunks/framework.ARG558ZT.js";const g=JSON.parse('{"title":"CS coverage map","description":"","frontmatter":{},"headers":[],"relativePath":"cs-foundations/coverage-map.md","filePath":"cs-foundations/coverage-map.md"}'),i={name:"cs-foundations/coverage-map.md"};function s(o,e,c,d,l,p){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="cs-coverage-map" tabindex="-1">CS coverage map <a class="header-anchor" href="#cs-coverage-map" aria-label="Permalink to “CS coverage map”">​</a></h1><p><strong>Material scope:</strong> practical foundations for JavaScript, TypeScript and Node.js. Coverage is based on reading explanations and implementations, not counting headings. This map reconciles CS-01–08 from the historical extension tracker; their learner outcomes remain <strong>still required</strong>.</p><p>“Confirmed” means an explanation and its worked reasoning were inspected. “Added” and “expanded” identify this round&#39;s changes. Depth is a material target, not a learner proficiency claim. Runtime/network/database chapters remain canonical; this course does not duplicate them or claim a complete operating-systems curriculum.</p><h2 id="algorithms-and-representations" tabindex="-1">Algorithms and representations <a class="header-anchor" href="#algorithms-and-representations" aria-label="Permalink to “Algorithms and representations”">​</a></h2><h3 id="cost-model-o-ω-θ-worst-average-amortized-cs-01" tabindex="-1">Cost model, O/Ω/Θ, worst/average/amortized; CS-01 <a class="header-anchor" href="#cost-model-o-ω-θ-worst-average-amortized-cs-01" aria-label="Permalink to “Cost model, O/Ω/Θ, worst/average/amortized; CS-01”">​</a></h3><p><a href="./complexity-and-cost.html">Complexity</a>; original Big O discussion distinguished cost dimensions but mixed traversal into the page</p><p><strong>Prerequisites:</strong> Functions, loops, arrays, simple algebra. <strong>Depth/action:</strong> Essential; expanded tight bounds, aggregate resizing proof and hidden copying costs.</p><p><strong>Worked evidence:</strong> Membership n×q versus reusable index; doubling copies; output lower bound. <strong>Practice:</strong> <a href="./../practice/cs-foundations/cost-and-search.html#cs-p01-cost-and-membership">CS-P01</a>.</p><h3 id="arrays-maps-sets-and-equality-cs-02" tabindex="-1">Arrays, maps, sets and equality; CS-02 <a class="header-anchor" href="#arrays-maps-sets-and-equality-cs-02" aria-label="Permalink to “Arrays, maps, sets and equality; CS-02”">​</a></h3><p><a href="./data-structures.html">Structures</a> plus <a href="./../senior_growth/General_ES6/What_is_ES6_Map_What_is_the_difference_between_Map_17be8106c24d808caa13f8ae4a80115c.html#equality-ownership-ordering-and-serialization">existing Map/WeakMap/Object explanation</a></p><p><strong>Prerequisites:</strong> Values, references, arrays/objects. <strong>Depth/action:</strong> Essential; existing SameValueZero/object-identity/serialization cases confirmed; representation/cost selection expanded.</p><p><strong>Worked evidence:</strong> NaN/±0, two equal-looking objects, stored undefined and index invalidation. <strong>Practice:</strong> CS-P01; <a href="./../practice/cs-foundations/collections-and-queues.html#cs-p04-bounded-fifo">CS-P04</a>; optional cache.</p><h3 id="stack-fifo-deque-and-linked-list-cs-02" tabindex="-1">Stack, FIFO, deque and linked list; CS-02 <a class="header-anchor" href="#stack-fifo-deque-and-linked-list-cs-02" aria-label="Permalink to “Stack, FIFO, deque and linked list; CS-02”">​</a></h3><p><a href="./data-structures.html#stacks-queues-and-linked-nodes">Structures</a>, <a href="./../workbench/cs-foundations/collections.html#fixed-capacity-fifo">bounded FIFO</a></p><p><strong>Prerequisites:</strong> Array indexing, mutation/ownership. <strong>Depth/action:</strong> Essential selection/invariants; ring queue added, list/deque costs explained; implementing a general list/deque optional.</p><p><strong>Worked evidence:</strong> Wraparound, clearing consumed slots, full/empty contract; known-node versus lookup cost. <strong>Practice:</strong> CS-P04.</p><h3 id="binary-heap-priority-queue-cs-02" tabindex="-1">Binary heap / priority queue; CS-02 <a class="header-anchor" href="#binary-heap-priority-queue-cs-02" aria-label="Permalink to “Binary heap / priority queue; CS-02”">​</a></h3><p><a href="./priority-queues.html">Priority scheduling</a></p><p><strong>Prerequisites:</strong> Array/tree indices, invariants, logarithms. <strong>Depth/action:</strong> Essential small scheduler; heap added, not a binary search tree or JS memory heap.</p><p><strong>Worked evidence:</strong> Sift-up/down trace, equal-priority sequence tie, bounded capacity. <strong>Practice:</strong> <a href="./../practice/cs-foundations/dependency-explorer.html#cs-p06-priority-scheduler">CS-P06</a>.</p><h3 id="linear-and-binary-search-cs-03" tabindex="-1">Linear and binary search; CS-03 <a class="header-anchor" href="#linear-and-binary-search-cs-03" aria-label="Permalink to “Linear and binary search; CS-03”">​</a></h3><p><a href="./binary-search.html">Binary search</a>; old page had a class-table mention only</p><p><strong>Prerequisites:</strong> Sorted order, loops, interval notation. <strong>Depth/action:</strong> Essential; lower-bound proof and wrapper added.</p><p><strong>Worked evidence:</strong> Empty/duplicate/absent/end boundary trace; shrinking half-open interval. <strong>Practice:</strong> <a href="./../practice/cs-foundations/cost-and-search.html#cs-p02-lower-bound">CS-P02</a>.</p><h3 id="sorting-comparator-stability-quicksort-cs-03" tabindex="-1">Sorting, comparator/stability, quicksort; CS-03 <a class="header-anchor" href="#sorting-comparator-stability-quicksort-cs-03" aria-label="Permalink to “Sorting, comparator/stability, quicksort; CS-03”">​</a></h3><p><a href="./sorting.html">Sorting</a>; original quicksort source and memory analysis inspected</p><p><strong>Prerequisites:</strong> Search invariants, arrays, recursion. <strong>Depth/action:</strong> Essential; corrected source-specific stability, probabilistic assumptions and costs; insertion/merge explained for selection.</p><p><strong>Worked evidence:</strong> Last-pivot partition induction, exact sorted-input counts, balanced/unbalanced allocation. <strong>Practice:</strong> <a href="./../practice/cs-foundations/sorting.html">CS-P03</a>.</p><h3 id="recursion-iteration-and-termination-cs-07" tabindex="-1">Recursion, iteration and termination; CS-07 <a class="header-anchor" href="#recursion-iteration-and-termination-cs-07" aria-label="Permalink to “Recursion, iteration and termination; CS-07”">​</a></h3><p><a href="./reasoning-and-recursion.html">Reasoning</a>, <a href="./../senior_growth/Other/What_is_memoization.html#correct-keys-ownership-and-invalidation">existing memoization</a></p><p><strong>Prerequisites:</strong> Functions and call stack. <strong>Depth/action:</strong> Essential; unified proof method added; cache identity/eviction limits confirmed; deeper dynamic programming optional.</p><p><strong>Worked evidence:</strong> Factorial induction/loop invariant, quicksort decreasing length, DFS frames. <strong>Practice:</strong> CS-P03, CS-P05; optional memoization extension.</p><h3 id="trees-bst-ordering-graph-representation-cs-02-03" tabindex="-1">Trees, BST ordering, graph representation; CS-02/03 <a class="header-anchor" href="#trees-bst-ordering-graph-representation-cs-02-03" aria-label="Permalink to “Trees, BST ordering, graph representation; CS-02/03”">​</a></h3><p><a href="./trees-graphs-traversal.html">Traversal</a>; original bounded TypeScript BFS/DFS/inorder read in full and retained</p><p><strong>Prerequisites:</strong> Stacks/FIFO, Map/Set, recursion. <strong>Depth/action:</strong> Essential; dedicated home and proofs added; balanced-tree implementation optional.</p><p><strong>Worked evidence:</strong> Cycle/shared-child rejection, non-BST inorder counterexample, adjacency versus matrix costs. <strong>Practice:</strong> <a href="./../practice/cs-foundations/dependency-explorer.html#cs-p05-note-dependency-explorer">CS-P05</a>.</p><h3 id="bfs-dfs-and-disconnected-cyclic-inputs-cs-03" tabindex="-1">BFS/DFS and disconnected/cyclic inputs; CS-03 <a class="header-anchor" href="#bfs-dfs-and-disconnected-cyclic-inputs-cs-03" aria-label="Permalink to “BFS/DFS and disconnected/cyclic inputs; CS-03”">​</a></h3><p><a href="./trees-graphs-traversal.html#bfs-distance-invariant">Traversal</a> and <a href="./../workbench/cs-foundations/traversals.html">canonical sources</a></p><p><strong>Prerequisites:</strong> Graph representation, queue/stack. <strong>Depth/action:</strong> Essential; confirmed original behavior; explicitly distinguishes reachability, shortest hops, cycle detection and topological order.</p><p><strong>Worked evidence:</strong> a→b,c; b→d; c→d; d→a; isolated z; independent distance oracle in checks. <strong>Practice:</strong> CS-P05.</p><h3 id="contracts-invariants-counterexamples-and-testing-cs-07" tabindex="-1">Contracts, invariants, counterexamples and testing; CS-07 <a class="header-anchor" href="#contracts-invariants-counterexamples-and-testing-cs-07" aria-label="Permalink to “Contracts, invariants, counterexamples and testing; CS-07”">​</a></h3><p><a href="./reasoning-and-recursion.html">Reasoning</a>, <a href="./../node-js/module-04-testing.html#_15-contract-property-and-concurrency-testing">Node property/concurrency tests</a></p><p><strong>Prerequisites:</strong> Functions, assertions; async for concurrency continuation. <strong>Depth/action:</strong> Essential proof/testing method; expanded source-level proof; testing is evidence rather than proof of all inputs.</p><p><strong>Worked evidence:</strong> Sortedness + permutation, search partition, FIFO/heap invariants, reproducible failures. <strong>Practice:</strong> All CS-P01–06; existing P-330/P-331/P-332 integration.</p><h2 id="existing-systems-continuations" tabindex="-1">Existing systems continuations <a class="header-anchor" href="#existing-systems-continuations" aria-label="Permalink to “Existing systems continuations”">​</a></h2><p>These concepts were reconciled against the actual named sections. Their depth remains applied/intermediate and their separate environment/practice requirements survive. They are not prerequisites to implement binary search.</p><h3 id="cs-04-stack-heap-gc-process-thread-event-loop-cancellation" tabindex="-1">CS-04: stack, heap, GC, process/thread, event loop, cancellation <a class="header-anchor" href="#cs-04-stack-heap-gc-process-thread-event-loop-cancellation" aria-label="Permalink to “CS-04: stack, heap, GC, process/thread, event loop, cancellation”">​</a></h3><p><strong>Teaching owner:</strong> <a href="./../node-js/module-01-nodejs-foundations.html#runtime-architecture-at-a-glance">Node foundations</a>, <a href="./../node-js/module-01-nodejs-foundations.html#_8-event-loop-deep-dive">scheduling</a>, <a href="./../node-js/module-11-performance-diagnostics.html">diagnostics</a>; <a href="./../senior_growth/General_ES6/Explain_JavaScript_Code_Execution_177e8106c24d80a0817df62da9bac253.html">JS execution</a>.</p><p><strong>Prerequisites/depth:</strong> JS functions/promises; applied runtime. GC is not timely resource cleanup; <code>async</code> does not parallelize CPU work.</p><p><strong>Worked example/practice:</strong> Existing limiter/worker, event-loop delay and owned cancellation; <a href="./../practice/backend-project.html#p-332">P-332</a>, <a href="./../practice/node-js/core-project.html">Node core project</a>.</p><h3 id="cs-04-races-serialization-locks" tabindex="-1">CS-04: races, serialization, locks <a class="header-anchor" href="#cs-04-races-serialization-locks" aria-label="Permalink to “CS-04: races, serialization, locks”">​</a></h3><p><strong>Teaching owner:</strong> <a href="./../node-js/module-08-postgresql-mikroorm.html#_22-locking-deadlocks-and-safe-retries">Database locking</a>, <a href="./../node-js/module-04-testing.html#concurrency-tests">concurrency tests</a>.</p><p><strong>Prerequisites/depth:</strong> Async ownership and transactions; applied rather than OS mutex implementation.</p><p><strong>Worked example/practice:</strong> Two reservations/conditional update, lock ordering, retry-safe callback; P-331/P-332.</p><h3 id="cs-05-dns-tcp-tls-http-and-framing" tabindex="-1">CS-05: DNS/TCP/TLS/HTTP and framing <a class="header-anchor" href="#cs-05-dns-tcp-tls-http-and-framing" aria-label="Permalink to “CS-05: DNS/TCP/TLS/HTTP and framing”">​</a></h3><p><strong>Teaching owner:</strong> <a href="./../node-js/module-05-networking.html#_9-https-net-and-dns">Networking</a>, especially TCP framing and lookup/resolve differences.</p><p><strong>Prerequisites/depth:</strong> Bytes, streams, HTTP lifecycle; applied network stack.</p><p><strong>Worked example/practice:</strong> Split/combine TCP chunks, bounded fetch/deadline; existing <a href="./../practice/node-js/module-05-networking.html">network exercises</a>, P-332.</p><h3 id="cs-05-partial-failure-ordering-delivery-idempotency" tabindex="-1">CS-05: partial failure, ordering, delivery/idempotency <a class="header-anchor" href="#cs-05-partial-failure-ordering-delivery-idempotency" aria-label="Permalink to “CS-05: partial failure, ordering, delivery/idempotency”">​</a></h3><p><strong>Teaching owner:</strong> <a href="./../node-js/module-12-resilient-distributed-systems.html#_1-the-distributed-systems-mental-model">Distributed failure model</a>, <a href="./../node-js/jobs-and-schedules.html">jobs</a>.</p><p><strong>Prerequisites/depth:</strong> One service first; distributed continuation.</p><p><strong>Worked example/practice:</strong> Lost reply after committed effect, confirm/ack crash windows, outbox/receipt; existing jobs practice, P-331/P-333.</p><h3 id="cs-06-modeling-constraints-indexes-query-plans" tabindex="-1">CS-06: modeling, constraints, indexes, query plans <a class="header-anchor" href="#cs-06-modeling-constraints-indexes-query-plans" aria-label="Permalink to “CS-06: modeling, constraints, indexes, query plans”">​</a></h3><p><strong>Teaching owner:</strong> <a href="./../node-js/module-08-postgresql-mikroorm.html#_1-relational-database-mental-model">Relational model</a>, <a href="./../node-js/module-08-postgresql-mikroorm.html#_9-indexes-and-query-plans">indexes</a>, <a href="./../workbench/node-js/database/sql-queries.html">SQL collection</a>.</p><p><strong>Prerequisites/depth:</strong> Relations, SQL; applied database reasoning.</p><p><strong>Worked example/practice:</strong> Keys/FKs, joins/NULL/grouping, composite index and EXPLAIN; existing SQL practice and P-331.</p><h3 id="cs-06-acid-isolation-locking-recovery" tabindex="-1">CS-06: ACID/isolation/locking/recovery <a class="header-anchor" href="#cs-06-acid-isolation-locking-recovery" aria-label="Permalink to “CS-06: ACID/isolation/locking/recovery”">​</a></h3><p><strong>Teaching owner:</strong> <a href="./../node-js/module-08-postgresql-mikroorm.html#_10-transactions-and-acid">Transactions</a>, <a href="./../node-js/module-08-postgresql-mikroorm.html#_11-isolation-and-concurrency">isolation</a>, <a href="./../node-js/database-recovery.html">recovery</a>.</p><p><strong>Prerequisites/depth:</strong> SQL, owned database environment; continuation.</p><p><strong>Worked example/practice:</strong> Conditional inventory update, deadlock/retry, separate-target restore; P-331/P-333.</p><h3 id="cs-07-state-transitions-at-real-boundaries" tabindex="-1">CS-07: state transitions at real boundaries <a class="header-anchor" href="#cs-07-state-transitions-at-real-boundaries" aria-label="Permalink to “CS-07: state transitions at real boundaries”">​</a></h3><p><strong>Teaching owner:</strong> <a href="./../node-js/module-10-production-ready-applications.html">Node lifecycle</a>, <a href="./../node-js/module-04-testing.html#_15-contract-property-and-concurrency-testing">testing</a>.</p><p><strong>Prerequisites/depth:</strong> Contracts/invariants, async cleanup.</p><p><strong>Worked example/practice:</strong> Startup→ready→draining→closed, denial and failure tests; existing Node specs. No new agent-workflow work credited.</p><h3 id="cs-08-coverage-and-independent-checkpoints" tabindex="-1">CS-08: coverage and independent checkpoints <a class="header-anchor" href="#cs-08-coverage-and-independent-checkpoints" aria-label="Permalink to “CS-08: coverage and independent checkpoints”">​</a></h3><p><strong>Teaching owner:</strong> This map, <a href="./">reading order</a>, <a href="./../practice/cs-foundations/">practice sequence</a>.</p><p><strong>Prerequisites/depth:</strong> CS-P01–06 build on one another.</p><p><strong>Worked example/practice:</strong> New organization and specs; learner results remain outstanding.</p><h2 id="reconciliation-limits" tabindex="-1">Reconciliation limits <a class="header-anchor" href="#reconciliation-limits" aria-label="Permalink to “Reconciliation limits”">​</a></h2><p>The original Big O membership/traversal and quicksort exercises are preserved <a href="./../practice/cs-foundations/retained-exercises.html">verbatim in practice</a>; their requirements are mapped to CS-P01/P03/P05. The existing Map cache assignment maps to the optional CS-P04 extension. Existing Node P-331–333 stay separate and unchanged. The memoization and shared execution/binding requirements are also preserved in practice as optional JavaScript continuations, rather than additional core projects.</p><p>The essential scope is covered by the teaching owners above. Balanced search trees, general linked-list/deque implementations, weighted shortest paths, topological sorting/cycle classification, advanced dynamic programming, OS scheduling/memory models and distributed consensus are explicitly optional extensions. A basic visited-set DFS is not evidence of those algorithms. No headings-only or uninspected external course receives coverage credit.</p>',81)])])}const m=a(i,[["render",s]]);export{g as __pageData,m as default};
